package replay_test

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"testing"

	"github.com/nanolathe-gg/nanolathe/internal/community"
	"github.com/nanolathe-gg/nanolathe/internal/gameplay"
	"github.com/nanolathe-gg/nanolathe/internal/headless"
	"github.com/nanolathe-gg/nanolathe/internal/replay"
	"github.com/nanolathe-gg/nanolathe/internal/session"
)

// These small files were generated by the v1 writer from revision 97eed60e5
// and the original v2 writer from 431c9f327 using portableFS and the recording
// helpers in this package (60 local pumps or 120 online ticks). Every map,
// unit, script and command is authored here; no retail bytes are included.
// Keeping the original bytes and final checksums locks compatibility with
// the historical writer rather than reconstructing it with today's codec.
func TestHistoricalRecordingsStillPlay(t *testing.T) {
	fs := portableFS(t)
	for _, fixture := range []struct {
		name    string
		version uint16
	}{
		{"v1-strict-3.1-skirmish", 1}, {"v1-modern-skirmish", 1}, {"v1-online-skirmish", 1}, {"v2-original-modern-skirmish", 2},
	} {
		name := fixture.name
		t.Run(name, func(t *testing.T) {
			data, err := os.ReadFile(filepath.Join("testdata", name+".nlreplay"))
			if err != nil {
				t.Fatal(err)
			}
			metadata, err := os.ReadFile(filepath.Join("testdata", name+".json"))
			if err != nil {
				t.Fatal(err)
			}
			var want struct {
				Ticks uint32
				Final [32]byte
			}
			if err := json.Unmarshal(metadata, &want); err != nil {
				t.Fatal(err)
			}
			r, err := replay.NewReader(data)
			if err != nil {
				t.Fatal(err)
			}
			h := r.Header()
			if h.FileVersion() != fixture.version {
				t.Fatalf("version %d, want %d", h.FileVersion(), fixture.version)
			}
			config, err := h.Configuration()
			if err != nil {
				t.Fatal(err)
			}
			encoded, err := session.EncodeMatchConfig(config)
			if err != nil || !bytes.Equal(encoded, h.Config) || config.Digest() != h.Identity.Configuration {
				t.Fatalf("historical configuration bytes or identity changed: %v", err)
			}
			s, err := replay.Compose(h, replay.Content{FS: fs})
			if err != nil {
				t.Fatal(err)
			}
			p, err := replay.NewPlayer(s, r)
			if err != nil {
				t.Fatal(err)
			}
			for !p.Done() {
				if _, err := p.Step(17); err != nil && !errors.Is(err, io.EOF) {
					t.Fatal(err)
				}
			}
			if p.Tick() != want.Ticks || p.Verified() != int(want.Ticks/30) || s.UnitStateChecksum() != want.Final {
				t.Fatalf("tick %d, verified %d, final %x; want tick %d and final %x", p.Tick(), p.Verified(), s.UnitStateChecksum(), want.Ticks, want.Final)
			}
			if _, err := replay.NewWriter(io.Discard, h); fixture.version == 1 && !errors.Is(err, replay.ErrUnsupportedVersion) {
				t.Fatalf("a historical header must not be relabeled as v2: %v", err)
			} else if fixture.version == 2 && err != nil {
				t.Fatal(err)
			}
		})
	}
}

// Descriptive additions in either header or configuration retain the same
// recorded battle. Required fields have their own explicit refusal tests;
// this test proves that skipping optional fields still checks the stream.
func TestOptionalReplayMetadataStillPlays(t *testing.T) {
	fs := portableFS(t)
	cfg := session.DirectSkirmishConfig(portableMap)
	cfg.Gameplay, cfg.UnitLimit, cfg.Location = gameplay.Modern, 20, 1
	zero := 0
	request := headless.FreshBattleRequest{Kind: headless.ScenarioSkirmish, Map: portableMap, Skirmish: cfg, Gameplay: gameplay.Modern,
		CommunitySources: session.CommunitySources{Player: community.Overrides{UnitLimit: &zero}},
		SimulationSeed:   7, CRTSeed: 11, FS: fs, LocalOwner: -1}
	rec := recordSinglePlayer(t, request, 60)
	rec.data = rewriteHeader(t, rec.data, func(h *replay.Header) {
		h.Extensions = []replay.HeaderExtension{{ID: 42, Data: []byte("future descriptive metadata")}}
		config, err := h.Configuration()
		if err != nil {
			t.Fatal(err)
		}
		q := config.Request()
		q.Extensions = []session.MatchConfigExtension{{ID: 64, Data: []byte("future configuration annotation")}}
		config, err = session.ResolveMatchConfig(q)
		if err != nil {
			t.Fatal(err)
		}
		h.Config, err = session.EncodeMatchConfig(config)
		if err != nil {
			t.Fatal(err)
		}
		h.Identity.Configuration = config.Digest()
	}, func(*replay.Entry) bool { return true })
	checkSinglePlayerPlayback(t, rec, replay.Content{FS: fs})
}
